-- Fixed source116 identity-only target correspondence. No byte authentication,
-- registry activation, runtime grant, processing admission or auth-writer fence.
-- Host must consume the actual receiver-owned identity target callback first.
CREATE SCHEMA wm_identity_target_load;
REVOKE ALL ON SCHEMA wm_identity_target_load FROM PUBLIC;
CREATE FUNCTION wm_identity_target_load.assert_owner_profile() RETURNS void
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,pg_temp AS $$
DECLARE own name; r record; p jsonb; actual jsonb; pin jsonb; f pg_proc;
BEGIN
 SELECT pg_get_userbyid(relowner) INTO own FROM pg_class WHERE oid='public.restore_processing_admission'::regclass;
 IF current_user IS DISTINCT FROM session_user OR session_user IS DISTINCT FROM own
  OR EXISTS(SELECT 1 FROM pg_roles WHERE rolname=session_user AND (rolsuper OR rolbypassrls))
 THEN RAISE EXCEPTION 'IDENTITY_TARGET_OWNER_REQUIRED' USING ERRCODE='42501'; END IF;
 IF (SELECT count(*) FROM public.schema_migrations)<>107 OR (SELECT max(version) FROM public.schema_migrations)<>107
  OR to_regprocedure('public.save_check_in_template_v1(jsonb)') IS NOT NULL
  OR to_regprocedure('public.read_race_manual_public_preview_source_v1(uuid)') IS NOT NULL
  OR (SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname NOT LIKE 'pg_%' AND n.nspname<>'information_schema' AND c.relkind IN ('r','p'))<>222
 THEN RAISE EXCEPTION 'IDENTITY_TARGET_FIXED116_PROFILE_REQUIRED'; END IF;
 FOR p IN SELECT profile_row.value FROM jsonb_array_elements('[{"name":"login_attempt","columns":[{"name":"state_hash","type":"text","notNull":true,"default":null},{"name":"browser_hash","type":"text","notNull":true,"default":null},{"name":"nonce","type":"text","notNull":true,"default":null},{"name":"verifier","type":"text","notNull":true,"default":null},{"name":"expires_at","type":"timestamp with time zone","notNull":true,"default":null},{"name":"created_at","type":"timestamp with time zone","notNull":true,"default":"clock_timestamp()"}],"constraints":[{"name":"login_attempt_browser_hash_check","type":"c","deferrable":false,"deferred":false,"definition":"CHECK ((browser_hash ~ ''^[a-f0-9]{64}$''::text))"},{"name":"login_attempt_nonce_check","type":"c","deferrable":false,"deferred":false,"definition":"CHECK (((length(nonce) >= 16) AND (length(nonce) <= 256)))"},{"name":"login_attempt_pkey","type":"p","deferrable":false,"deferred":false,"definition":"PRIMARY KEY (state_hash)"},{"name":"login_attempt_state_hash_check","type":"c","deferrable":false,"deferred":false,"definition":"CHECK ((state_hash ~ ''^[a-f0-9]{64}$''::text))"},{"name":"login_attempt_verifier_check","type":"c","deferrable":false,"deferred":false,"definition":"CHECK (((length(verifier) >= 43) AND (length(verifier) <= 128)))"}]},{"name":"logout_token_replay","columns":[{"name":"issuer","type":"text","notNull":true,"default":null},{"name":"jti_hash","type":"text","notNull":true,"default":null},{"name":"subject","type":"text","notNull":false,"default":null},{"name":"provider_session_id","type":"text","notNull":false,"default":null},{"name":"received_at","type":"timestamp with time zone","notNull":true,"default":"clock_timestamp()"}],"constraints":[{"name":"logout_token_replay_check","type":"c","deferrable":false,"deferred":false,"definition":"CHECK (((subject IS NOT NULL) OR (provider_session_id IS NOT NULL)))"},{"name":"logout_token_replay_issuer_check","type":"c","deferrable":false,"deferred":false,"definition":"CHECK (((length(issuer) >= 1) AND (length(issuer) <= 2048)))"},{"name":"logout_token_replay_jti_hash_check","type":"c","deferrable":false,"deferred":false,"definition":"CHECK ((jti_hash ~ ''^[a-f0-9]{64}$''::text))"},{"name":"logout_token_replay_pkey","type":"p","deferrable":false,"deferred":false,"definition":"PRIMARY KEY (issuer, jti_hash)"},{"name":"logout_token_replay_provider_session_id_check","type":"c","deferrable":false,"deferred":false,"definition":"CHECK (((length(provider_session_id) >= 1) AND (length(provider_session_id) <= 255)))"},{"name":"logout_token_replay_subject_check","type":"c","deferrable":false,"deferred":false,"definition":"CHECK (((length(subject) >= 1) AND (length(subject) <= 255)))"}]},{"name":"native_exchange_code","columns":[{"name":"code_hash","type":"text","notNull":true,"default":null},{"name":"code_challenge","type":"text","notNull":true,"default":null},{"name":"issuer","type":"text","notNull":true,"default":null},{"name":"subject","type":"text","notNull":true,"default":null},{"name":"provider_session_id","type":"text","notNull":false,"default":null},{"name":"login_started_at","type":"timestamp with time zone","notNull":true,"default":null},{"name":"expires_at","type":"timestamp with time zone","notNull":true,"default":null}],"constraints":[{"name":"native_exchange_code_code_challenge_check","type":"c","deferrable":false,"deferred":false,"definition":"CHECK ((code_challenge ~ ''^[A-Za-z0-9_-]{43}$''::text))"},{"name":"native_exchange_code_code_hash_check","type":"c","deferrable":false,"deferred":false,"definition":"CHECK ((code_hash ~ ''^[a-f0-9]{64}$''::text))"},{"name":"native_exchange_code_issuer_check","type":"c","deferrable":false,"deferred":false,"definition":"CHECK (((length(issuer) >= 1) AND (length(issuer) <= 2048)))"},{"name":"native_exchange_code_pkey","type":"p","deferrable":false,"deferred":false,"definition":"PRIMARY KEY (code_hash)"},{"name":"native_exchange_code_provider_session_id_check","type":"c","deferrable":false,"deferred":false,"definition":"CHECK (((length(provider_session_id) >= 1) AND (length(provider_session_id) <= 255)))"},{"name":"native_exchange_code_subject_check","type":"c","deferrable":false,"deferred":false,"definition":"CHECK (((length(subject) >= 1) AND (length(subject) <= 255)))"}]},{"name":"native_login_attempt","columns":[{"name":"state_hash","type":"text","notNull":true,"default":null},{"name":"nonce","type":"text","notNull":true,"default":null},{"name":"verifier","type":"text","notNull":true,"default":null},{"name":"code_challenge","type":"text","notNull":true,"default":null},{"name":"created_at","type":"timestamp with time zone","notNull":true,"default":"clock_timestamp()"},{"name":"expires_at","type":"timestamp with time zone","notNull":true,"default":null}],"constraints":[{"name":"native_login_attempt_code_challenge_check","type":"c","deferrable":false,"deferred":false,"definition":"CHECK ((code_challenge ~ ''^[A-Za-z0-9_-]{43}$''::text))"},{"name":"native_login_attempt_nonce_check","type":"c","deferrable":false,"deferred":false,"definition":"CHECK (((length(nonce) >= 16) AND (length(nonce) <= 256)))"},{"name":"native_login_attempt_pkey","type":"p","deferrable":false,"deferred":false,"definition":"PRIMARY KEY (state_hash)"},{"name":"native_login_attempt_state_hash_check","type":"c","deferrable":false,"deferred":false,"definition":"CHECK ((state_hash ~ ''^[a-f0-9]{64}$''::text))"},{"name":"native_login_attempt_verifier_check","type":"c","deferrable":false,"deferred":false,"definition":"CHECK ((verifier ~ ''^[A-Za-z0-9_-]{43,128}$''::text))"}]},{"name":"session","columns":[{"name":"token_hash","type":"text","notNull":true,"default":null},{"name":"session_id","type":"uuid","notNull":true,"default":"gen_random_uuid()"},{"name":"athlete_id","type":"uuid","notNull":true,"default":null},{"name":"csrf_token","type":"text","notNull":true,"default":null},{"name":"expires_at","type":"timestamp with time zone","notNull":true,"default":null},{"name":"provider_session_id","type":"text","notNull":false,"default":null},{"name":"kind","type":"text","notNull":true,"default":"''browser''::text"}],"constraints":[{"name":"session_athlete_id_fkey","type":"f","deferrable":false,"deferred":false,"definition":"FOREIGN KEY (athlete_id) REFERENCES identity_private.account(athlete_id)"},{"name":"session_csrf_token_check","type":"c","deferrable":false,"deferred":false,"definition":"CHECK (((length(csrf_token) >= 32) AND (length(csrf_token) <= 256)))"},{"name":"session_kind_check","type":"c","deferrable":false,"deferred":false,"definition":"CHECK ((kind = ANY (ARRAY[''browser''::text, ''native''::text])))"},{"name":"session_pkey","type":"p","deferrable":false,"deferred":false,"definition":"PRIMARY KEY (token_hash)"},{"name":"session_provider_session_id_check","type":"c","deferrable":false,"deferred":false,"definition":"CHECK (((length(provider_session_id) >= 1) AND (length(provider_session_id) <= 255)))"},{"name":"session_session_id_key","type":"u","deferrable":false,"deferred":false,"definition":"UNIQUE (session_id)"},{"name":"session_token_hash_check","type":"c","deferrable":false,"deferred":false,"definition":"CHECK ((token_hash ~ ''^[a-f0-9]{64}$''::text))"}]}]'::jsonb) AS profile_row(value) LOOP
  SELECT jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notNull',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid)) ORDER BY a.attnum) INTO actual
   FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=format('identity_private.%I',p->>'name')::regclass AND a.attnum>0 AND NOT a.attisdropped;
  IF actual IS DISTINCT FROM p->'columns' THEN RAISE EXCEPTION 'IDENTITY_TARGET_COLUMN_PROFILE_REJECTED'; END IF;
  SELECT jsonb_agg(jsonb_build_object('name',c.conname,'type',c.contype::text,'deferrable',c.condeferrable,'deferred',c.condeferred,'definition',pg_get_constraintdef(c.oid)) ORDER BY c.conname COLLATE "C") INTO actual FROM pg_constraint c WHERE c.conrelid=format('identity_private.%I',p->>'name')::regclass;
  IF actual IS DISTINCT FROM p->'constraints' OR EXISTS(SELECT 1 FROM pg_class c WHERE c.oid=format('identity_private.%I',p->>'name')::regclass AND (pg_get_userbyid(c.relowner)<>own OR c.relrowsecurity OR c.relforcerowsecurity)) THEN RAISE EXCEPTION 'IDENTITY_TARGET_RELATION_PROFILE_REJECTED'; END IF;
  IF EXISTS(SELECT 1 FROM pg_trigger t WHERE t.tgrelid=format('identity_private.%I',p->>'name')::regclass AND NOT t.tgisinternal) OR EXISTS(SELECT 1 FROM pg_class c CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a WHERE c.oid=format('identity_private.%I',p->>'name')::regclass AND a.grantee<>c.relowner) THEN RAISE EXCEPTION 'IDENTITY_TARGET_RELATION_ACL_OR_TRIGGER_REJECTED'; END IF;
 END LOOP;
 IF (SELECT nspowner FROM pg_namespace WHERE nspname='identity_private') IS DISTINCT FROM (SELECT oid FROM pg_roles WHERE rolname=own) OR EXISTS(SELECT 1 FROM pg_namespace n CROSS JOIN LATERAL aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) a WHERE n.nspname='identity_private' AND a.grantee<>n.nspowner) THEN RAISE EXCEPTION 'IDENTITY_TARGET_SCHEMA_OWNER_REJECTED'; END IF;
 FOR pin IN SELECT pin_row.value FROM jsonb_array_elements('[{"signature":"public.auth_create_attempt(text, text, text, text, timestamptz)","bodyHash":"9910ecc09a49343161cf749a22d04d0f28e499eb68cb90a93c24f3b8b518a602"},{"signature":"public.auth_consume_attempt(text, text, timestamptz)","bodyHash":"ae504daf96cfc7e311aa7306ae3420cf2af474e9f8eeff2a404be462cc0ce0b0"},{"signature":"public.auth_consume_attempt_v2(text, text, timestamptz)","bodyHash":"8ef27ebd414c52df7553855cbb38ec72106375bfb80f610d0b18362394c1aad3"},{"signature":"public.auth_create_session(text, text, text, text, timestamptz, timestamptz, text, text, timestamptz)","bodyHash":"bb8cd355e51da57cc879233cfd7e649d7552a59f7829aa81dfa9ce4bfe5b48c0"},{"signature":"public.auth_find_session_v2(text, timestamptz, text)","bodyHash":"d5fc630da8e0c0c02a449913d47ecf265f980d51291648ea78f2ff8f2ac234f5"},{"signature":"public.auth_revoke_session(text)","bodyHash":"62b5a2498cd7fae8fa75351bd62f79c0a029009a9e37af90de638dcf903ee028"},{"signature":"public.auth_revoke_provider_sessions(text, text, timestamptz, text, text)","bodyHash":"4804214c123c73da4eaee1bf3ff0945a1b38939d14cb41fc30beca0eb82eb1c2"},{"signature":"public.auth_create_native_attempt(text, text, text, text, timestamptz)","bodyHash":"dcdeae19fcef394d2819eca9c0177394f7183c533e5f7ca11ed8df34f71fdf92"},{"signature":"public.auth_consume_native_attempt(text, timestamptz)","bodyHash":"b8d8cced66b931d72056fb680372f67c8437862c3da5f03b1f688df076186fe1"},{"signature":"public.auth_create_native_code(text, text, text, text, text, timestamptz, timestamptz, timestamptz)","bodyHash":"1543e9fd329f9f758b10bc84549ed30c73485078511e097f34caac82c81ed5f2"},{"signature":"public.auth_exchange_native_code(text, text, text, text, timestamptz, timestamptz)","bodyHash":"a34e2d615f615a4295a6ca10f9390cba6d252f8e3e5dd24120a10e131696bd55"}]'::jsonb) AS pin_row(value) LOOP
  SELECT * INTO f FROM pg_proc WHERE oid=to_regprocedure(pin->>'signature');
  IF NOT FOUND OR NOT f.prosecdef OR f.prokind<>'f' OR f.provolatile<>'v' OR f.proisstrict OR f.proowner IS DISTINCT FROM (SELECT oid FROM pg_roles WHERE rolname=own)
   OR f.proconfig IS DISTINCT FROM ARRAY['search_path=pg_catalog']::text[]
   OR encode(sha256(convert_to(f.prosrc,'UTF8')),'hex') IS DISTINCT FROM pin->>'bodyHash'
  THEN RAISE EXCEPTION 'IDENTITY_TARGET_AUTH_FUNCTION_PROFILE_REJECTED'; END IF;
  -- Reject real effective runtime EXECUTE, including inherited owner grants.
  -- Superuser/operator quiescence remains an external operational prerequisite.
  IF EXISTS(SELECT 1 FROM aclexplode(coalesce(f.proacl,acldefault('f',f.proowner))) a WHERE a.grantee<>f.proowner AND a.privilege_type='EXECUTE')
   OR EXISTS(SELECT 1 FROM pg_roles role WHERE role.rolname<>own AND NOT role.rolsuper AND NOT role.rolbypassrls AND has_function_privilege(role.oid,f.oid,'EXECUTE'))
  THEN RAISE EXCEPTION 'IDENTITY_TARGET_AUTH_RUNTIME_NOT_QUIESCENT'; END IF;
 END LOOP;
END $$;
REVOKE ALL ON FUNCTION wm_identity_target_load.assert_owner_profile() FROM PUBLIC;

CREATE FUNCTION wm_identity_target_load.apply_identity_target_v1(expected_control jsonb,partition jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,pg_temp SET TimeZone='UTC' SET DateStyle='ISO,YMD' AS $$
DECLARE control jsonb; c jsonb; e jsonb; v jsonb; prior jsonb; names text[]:=ARRAY['identity_private.login_attempt','identity_private.logout_token_replay','identity_private.native_exchange_code','identity_private.native_login_attempt','identity_private.session']; i integer; total numeric:=0; ledger_count integer:=0; previous_ordinal integer:=0; previous_key text[]; key text[]; stamp timestamptz;
BEGIN
 PERFORM public.manual_race_v2_assert_json_bound(expected_control);
 PERFORM public.manual_race_v2_assert_json_bound(partition);
 PERFORM wm_identity_target_load.assert_owner_profile();
 IF jsonb_typeof(expected_control)<>'object' OR expected_control-ARRAY['state','localRevision','generationId','targetNonce','targetIncarnation','admissionAllowed','targetAttested']<>'{}'::jsonb
  OR NOT(expected_control ?& ARRAY['state','localRevision','generationId','targetNonce','targetIncarnation','admissionAllowed','targetAttested'])
  OR expected_control->>'state' IS DISTINCT FROM 'CLOSED' OR expected_control->'admissionAllowed' IS DISTINCT FROM 'false'::jsonb OR expected_control->'targetAttested' IS DISTINCT FROM 'false'::jsonb
  OR jsonb_typeof(expected_control->'localRevision') IS DISTINCT FROM 'string' OR coalesce(expected_control->>'localRevision','')!~'^[1-9][0-9]{0,18}$'
  OR (expected_control->>'localRevision')::numeric>9223372036854775807
  OR jsonb_typeof(expected_control->'generationId') IS DISTINCT FROM 'string'
  OR jsonb_typeof(expected_control->'targetNonce') IS DISTINCT FROM 'string' OR jsonb_typeof(expected_control->'targetIncarnation') IS DISTINCT FROM 'string'
 THEN RAISE EXCEPTION 'IDENTITY_TARGET_CONTROL_REJECTED'; END IF;
 PERFORM pg_advisory_xact_lock(77210,1);
 control:=public.assert_restore_processing_closed((expected_control->>'localRevision')::bigint,(expected_control->>'targetNonce')::uuid,(expected_control->>'targetIncarnation')::uuid);
 IF control IS DISTINCT FROM expected_control THEN RAISE EXCEPTION 'IDENTITY_TARGET_CONTROL_REJECTED'; END IF;
 LOCK TABLE identity_private.login_attempt,identity_private.logout_token_replay,identity_private.native_exchange_code,identity_private.native_login_attempt,identity_private.session IN ACCESS EXCLUSIVE MODE;
 IF EXISTS(SELECT 1 FROM identity_private.login_attempt) OR EXISTS(SELECT 1 FROM identity_private.native_login_attempt) OR EXISTS(SELECT 1 FROM identity_private.native_exchange_code) OR EXISTS(SELECT 1 FROM identity_private.session) THEN RAISE EXCEPTION 'IDENTITY_TARGET_CREDENTIALS_NOT_EMPTY'; END IF;
 IF jsonb_typeof(partition)<>'object' OR partition-ARRAY['profile','census','rows']<>'{}'::jsonb OR NOT(partition ?& ARRAY['profile','census','rows']) OR partition->>'profile' IS DISTINCT FROM 'normal107-explicit108-116'
  OR jsonb_typeof(partition->'census') IS DISTINCT FROM 'array' OR jsonb_array_length(partition->'census')<>5
  OR jsonb_typeof(partition->'rows') IS DISTINCT FROM 'array' OR jsonb_array_length(partition->'rows')>5000
 THEN RAISE EXCEPTION 'IDENTITY_TARGET_PARTITION_REJECTED'; END IF;
 FOR i IN 0..4 LOOP
  c:=partition->'census'->i;
  IF jsonb_typeof(c)<>'object' OR c-ARRAY['relation','sourceCount','targetCount','disposition']<>'{}'::jsonb OR NOT(c ?& ARRAY['relation','sourceCount','targetCount','disposition'])
   OR c->>'relation' IS DISTINCT FROM names[i+1] OR jsonb_typeof(c->'sourceCount') IS DISTINCT FROM 'string' OR jsonb_typeof(c->'targetCount') IS DISTINCT FROM 'string'
   OR coalesce(c->>'sourceCount','')!~'^(0|[1-9][0-9]{0,3})$' OR (c->>'sourceCount')::int>5000
   OR c->>'targetCount' IS DISTINCT FROM (CASE WHEN i=1 THEN c->>'sourceCount' ELSE '0' END)
   OR c->>'disposition' IS DISTINCT FROM (CASE WHEN i=1 THEN 'retain_replay_deny_audit' ELSE 'invalidate_archived_credentials' END)
  THEN RAISE EXCEPTION 'IDENTITY_TARGET_CENSUS_REJECTED'; END IF;
  total:=total+(c->>'sourceCount')::int;
  IF i=1 THEN ledger_count:=(c->>'targetCount')::int; END IF;
 END LOOP;
 IF total>5000 OR jsonb_array_length(partition->'rows')<>ledger_count THEN RAISE EXCEPTION 'IDENTITY_TARGET_CENSUS_REJECTED'; END IF;
 FOR e IN SELECT source_row.value FROM jsonb_array_elements(partition->'rows') AS source_row(value) LOOP
  IF jsonb_typeof(e)<>'object' OR e-ARRAY['ordinal','relation','row','arrayLayouts']<>'{}'::jsonb OR NOT(e ?& ARRAY['ordinal','relation','row','arrayLayouts'])
   OR e->>'relation' IS DISTINCT FROM 'identity_private.logout_token_replay' OR e->'arrayLayouts' IS DISTINCT FROM '{}'::jsonb
   OR jsonb_typeof(e->'ordinal') IS DISTINCT FROM 'number' OR coalesce(e->>'ordinal','')!~'^[1-9][0-9]{0,3}$' OR (e->>'ordinal')::int>5000 OR (e->>'ordinal')::int<=previous_ordinal
  THEN RAISE EXCEPTION 'IDENTITY_TARGET_ROW_REJECTED'; END IF;
  previous_ordinal:=(e->>'ordinal')::int; v:=e->'row';
  IF jsonb_typeof(v)<>'object' OR v-ARRAY['issuer','jti_hash','subject','provider_session_id','received_at']<>'{}'::jsonb OR NOT(v ?& ARRAY['issuer','jti_hash','subject','provider_session_id','received_at'])
   OR jsonb_typeof(v->'issuer') IS DISTINCT FROM 'string' OR length(v->>'issuer') NOT BETWEEN 1 AND 2048
   OR jsonb_typeof(v->'jti_hash') IS DISTINCT FROM 'string' OR coalesce(v->>'jti_hash','')!~'^[a-f0-9]{64}$'
   OR jsonb_typeof(v->'subject') NOT IN ('string','null') OR (jsonb_typeof(v->'subject')='string' AND length(v->>'subject') NOT BETWEEN 1 AND 255)
   OR jsonb_typeof(v->'provider_session_id') NOT IN ('string','null') OR (jsonb_typeof(v->'provider_session_id')='string' AND length(v->>'provider_session_id') NOT BETWEEN 1 AND 255)
   OR (v->'subject'='null'::jsonb AND v->'provider_session_id'='null'::jsonb)
   OR jsonb_typeof(v->'received_at') IS DISTINCT FROM 'string' OR coalesce(v->>'received_at','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}Z$'
  THEN RAISE EXCEPTION 'IDENTITY_TARGET_ROW_REJECTED'; END IF;
  stamp:=(v->>'received_at')::timestamptz;
  IF to_char(stamp AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') IS DISTINCT FROM v->>'received_at' THEN RAISE EXCEPTION 'IDENTITY_TARGET_TIMESTAMP_REJECTED'; END IF;
  key:=ARRAY[v->>'issuer',v->>'jti_hash'];
  -- Exact source ordering uses opaque UTF16 semantic order, not database collation.
  IF previous_key IS NOT NULL AND (public.nutrition_copy_utf16_key(to_jsonb(key)::text)<=public.nutrition_copy_utf16_key(to_jsonb(previous_key)::text)) THEN RAISE EXCEPTION 'IDENTITY_TARGET_DUPLICATE_OR_ORDER_REJECTED'; END IF;
  previous_key:=key;
  SELECT jsonb_build_object('issuer',r.issuer,'jti_hash',r.jti_hash,'subject',r.subject,'provider_session_id',r.provider_session_id,'received_at',to_char(r.received_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')) INTO prior FROM identity_private.logout_token_replay r WHERE r.issuer=v->>'issuer' AND r.jti_hash=v->>'jti_hash';
  IF prior IS NOT NULL AND prior IS DISTINCT FROM v THEN RAISE EXCEPTION 'IDENTITY_TARGET_EXISTING_AUDIT_CONFLICT'; END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM identity_private.logout_token_replay r WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(partition->'rows') AS source_row(value) WHERE source_row.value->'row'->>'issuer'=r.issuer AND source_row.value->'row'->>'jti_hash'=r.jti_hash)) THEN RAISE EXCEPTION 'IDENTITY_TARGET_EXTRA_AUDIT_CONFLICT'; END IF;
 INSERT INTO identity_private.logout_token_replay(issuer,jti_hash,subject,provider_session_id,received_at)
 SELECT source_row.value->'row'->>'issuer',source_row.value->'row'->>'jti_hash',source_row.value->'row'->>'subject',source_row.value->'row'->>'provider_session_id',(source_row.value->'row'->>'received_at')::timestamptz FROM jsonb_array_elements(partition->'rows') AS source_row(value) ON CONFLICT(issuer,jti_hash) DO NOTHING;
 IF EXISTS(SELECT 1 FROM identity_private.logout_token_replay r WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(partition->'rows') AS source_row(value) WHERE source_row.value->'row'=jsonb_build_object('issuer',r.issuer,'jti_hash',r.jti_hash,'subject',r.subject,'provider_session_id',r.provider_session_id,'received_at',to_char(r.received_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')))) OR (SELECT count(*) FROM identity_private.logout_token_replay)<>ledger_count THEN RAISE EXCEPTION 'IDENTITY_TARGET_POSTIMAGE_REJECTED'; END IF;
 SET CONSTRAINTS ALL IMMEDIATE;
 PERFORM wm_identity_target_load.assert_owner_profile();
 IF public.assert_restore_processing_closed((expected_control->>'localRevision')::bigint,(expected_control->>'targetNonce')::uuid,(expected_control->>'targetIncarnation')::uuid) IS DISTINCT FROM control THEN RAISE EXCEPTION 'IDENTITY_TARGET_CONTROL_REJECTED'; END IF;
 RETURN jsonb_build_object('materializedScope','identity_private_five_relations_only','targetProfile','normal107-explicit108-116-plus125','auditCount',ledger_count::text,'credentialsEmpty',true,'control',control,'authority','none','admissionAllowed',false,'sourceAuthentication','host_callback_prerequisite','latestTail','not_checked');
END $$;
REVOKE ALL ON FUNCTION wm_identity_target_load.apply_identity_target_v1(jsonb,jsonb) FROM PUBLIC;
